def lru_misses(capacity: int, accesses: list[int]) -> int:
    """Number of cache misses for an LRU cache of the given capacity serving the accesses in order."""
    if capacity <= 0:
        return len(accesses)

    cache = {}
    order = []
    misses = 0

    for access in accesses:
        if access in cache:
            # Move accessed item to the end (most recently used)
            order.remove(access)
            order.append(access)
        else:
            # Cache miss
            misses += 1
            if len(cache) >= capacity:
                # Remove the least recently used item (first in order)
                lru_item = order.pop(0)
                del cache[lru_item]
            cache[access] = True
            order.append(access)

    return misses
```

