def parse_duration(s: str) -> int:
    """Seconds in a duration like "1h30m15s" (each of h, m, s optional, in that order); raise ValueError if invalid or empty."""
    if not s:
        raise ValueError("Duration string cannot be empty.")

    s = s.strip()
    if not s:
        raise ValueError("Duration string cannot be empty.")

    total_seconds = 0
    i = 0

    while i < len(s):
        if s[i].isdigit():
            # Parse the number
            num_str = ""
            while i < len(s) and s[i].isdigit():
                num_str += s[i]
                i += 1
            num = int(num_str)

            # Determine the unit based on the next character
            if i < len(s) and s[i] == 'h':
                total_seconds += num * 3600
                i += 1
            elif i < len(s) and s[i] == 'm':
                total_seconds += num * 60
                i += 1
            elif i < len(s) and s[i] == 's':
                total_seconds += num
                i += 1
            else:
                raise ValueError(f"Invalid character '{s[i]}' after number.")
        else:
            raise ValueError(f"Invalid character '{s[i]}' in duration string.")

    return total_seconds
